  var EXAM_DATES_KEY = "cse-syllabus-exam-dates-v1";
  var DSA_KEY = "dsaQuestions";
  var GOAL_KEY = "dsaDailyGoal";
  var TASK_KEY = "arise-daily-learning-tasks-v1";
  var FOCUS_KEY = "focusSessionsV2";
